package career.assistant.application.service;
import career.assistant.application.audit.*; import career.assistant.application.ats.*; import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.document.service.*; import career.assistant.jobscore.repository.JobScoreRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AutoApplyExecutionService {
 private final ApplicationRepository applications; private final JobScoreRepository scores; private final SubmissionAttemptService attempts; private final AshbySubmissionTransport transport; private final ApplicationNotificationService notifications; private final ResumeService resumes; private final CoverLetterService letters; private final boolean enabled,dryRun; private final int dailyLimit; private final java.math.BigDecimal minimum;
 public AutoApplyExecutionService(ApplicationRepository a,JobScoreRepository s,SubmissionAttemptService at,AshbySubmissionTransport t,ApplicationNotificationService n,ResumeService r,CoverLetterService l,@Value("${career.application.auto-apply-enabled:false}")boolean e,@Value("${career.application.dry-run:true}")boolean d,@Value("${career.application.max-real-submissions-daily:1}")int dl,@Value("${career.application.minimum-score:75}")java.math.BigDecimal m){applications=a;scores=s;attempts=at;transport=t;notifications=n;resumes=r;letters=l;enabled=e;dryRun=d;dailyLimit=dl;minimum=m;}
 public ExecutionResult execute(UUID id,boolean confirmation){String owner=subject();Application app=applications.findById(id).orElseThrow(()->new IllegalArgumentException("Application not found"));if(!confirmation)return blocked(id,"CONFIRMATION_REQUIRED","Explicit confirmation is required");if(!enabled||dryRun)return blocked(id,"FEATURE_DISABLED","Real auto-apply is disabled");if(app.getStatus()!=ApplicationStatus.READY_TO_APPLY)return blocked(id,"NOT_READY","Application is not READY_TO_APPLY");var score=scores.findByJob(app.getJob()).orElse(null);if(score==null||score.getScore()==null||score.getScore().compareTo(minimum)<0)return blocked(id,"SCORE_BELOW_THRESHOLD","Score is below the configured threshold");String url=app.getJob().getJobUrl();if(PublicAtsAdapters.parseAshbyUrl(url).isEmpty())return blocked(id,"UNSUPPORTED_ATS","Only an allowlisted Ashby posting is supported");if(!attempts.dailyLimitAvailable(owner,dailyLimit))return blocked(id,"DAILY_LIMIT","Daily confirmed-submission limit reached");if(app.getResumeVersionId()==null||app.getCoverLetterId()==null)return blocked(id,"DOCUMENTS_INCOMPLETE","Required generated documents are missing");SubmissionAttemptDto claim=attempts.claim(id,owner,"ASHBY",url,"application:"+id,"ashby:"+id);AshbySubmissionTransport.SubmissionPlan plan=new AshbySubmissionTransport.SubmissionPlan(url,null,Map.of("applicationId",id.toString()),List.of());AshbySubmissionResult result=transport.submit(plan,false);SubmissionAttemptState state=switch(result.outcome()){case CONFIRMED->SubmissionAttemptState.CONFIRMED;case UNCERTAIN->SubmissionAttemptState.UNCERTAIN;case REVIEW_REQUIRED,CAPTCHA_OR_CHALLENGE,SCHEMA_CHANGED->SubmissionAttemptState.REVIEW_REQUIRED;default->SubmissionAttemptState.FAILED;};attempts.finish(claim.id(),state,result.safeReason(),result.confirmationReference(),result.confirmationUrl());if(result.outcome()==AshbySubmissionResult.Outcome.CONFIRMED){app.setStatus(ApplicationStatus.AUTO_APPLIED);app.setConfirmationId(result.confirmationReference());app.setConfirmationUrl(result.confirmationUrl());app.setAppliedAt(java.time.OffsetDateTime.now());app.setSubmittedAt(app.getAppliedAt());applications.save(app);notifications.sendVerifiedSuccessOnce(app,score.getScore().toPlainString());}else if(state==SubmissionAttemptState.REVIEW_REQUIRED||state==SubmissionAttemptState.UNCERTAIN){app.setStatus(ApplicationStatus.PENDING_REVIEW);applications.save(app);}return new ExecutionResult(id,claim.id(),state,result.safeReason(),result.confirmationReference());}
 private ExecutionResult blocked(UUID id,String code,String reason){return new ExecutionResult(id,null,null,code+": "+reason,null);} private String subject(){var a=SecurityContextHolder.getContext().getAuthentication();if(a instanceof JwtAuthenticationToken j)return j.getToken().getSubject();return "authenticated-user";} public record ExecutionResult(UUID applicationId,UUID attemptId,SubmissionAttemptState state,String blocker,String confirmationReference){}
}
